import { useEffect, useRef } from 'react';

import { inlineImagesForExport } from 'hooks/useExportPdf/inlineImagesForExport';
import {
  usePageCacheBaseState,
  usePageCacheLoadingGate,
  useResolvedPageHash,
} from 'hooks/usePageCache/shared';
import { PageCacheService } from 'services/PageCacheService/PageCacheService';
import { compressToBase64, decompressFromBase64 } from 'utils/compression';
import {
  hydratePngCopyActions,
  stripPngCopyActions,
  stripPngCopyActionsFromHtml,
  TEMPLATE_SLIDE_TEST_ID_PREFIX,
  waitForCanvasStability,
} from 'utils/pageCache';

export interface UsePageCacheHtmlProps {
  pageName: string;
  containerRef: React.RefObject<HTMLDivElement>;
  enabled?: boolean;
  isPageReady?: boolean;
}

export interface UsePageCacheHtmlResult {
  cachedHtml: string | null;
  isCacheChecking: boolean;
  isCacheHit: boolean;
  isStaleHit: boolean;
  shouldRevalidate: boolean;
}

const collectStylesheets = (): string => {
  const rules: string[] = [];
  for (const sheet of Array.from(document.styleSheets)) {
    try {
      for (const rule of Array.from(sheet.cssRules)) {
        rules.push(rule.cssText);
      }
    } catch {
      // cross-origin stylesheet — skip
    }
  }
  return rules.join('\n');
};

const rasterizeCanvasElements = (
  source: HTMLElement,
  clone: HTMLElement,
): void => {
  const origCanvases = source.querySelectorAll('canvas');
  const clonedCanvases = clone.querySelectorAll('canvas');

  origCanvases.forEach((origCanvas, i) => {
    const clonedCanvas = clonedCanvases[i];
    if (!clonedCanvas) return;

    try {
      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = origCanvas.width;
      tempCanvas.height = origCanvas.height;
      const ctx = tempCanvas.getContext('2d');
      if (ctx) {
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, tempCanvas.width, tempCanvas.height);
        ctx.drawImage(origCanvas, 0, 0);
      }

      const dataUrl = tempCanvas.toDataURL('image/png');
      const img = document.createElement('img');
      img.src = dataUrl;
      img.style.cssText = 'display:block;max-width:100%;height:auto;';

      const parent = clonedCanvas.parentElement;
      if (parent) {
        parent.style.position = 'relative';
      }

      clonedCanvas.parentNode?.replaceChild(img, clonedCanvas);
    } catch {
      // canvas tainted or empty
    }
  });
};

const serializeDom = async (source: HTMLElement): Promise<string> => {
  const clone = source.cloneNode(true) as HTMLElement;

  rasterizeCanvasElements(source, clone);

  clone.querySelectorAll('script').forEach((s) => s.remove());
  clone.querySelectorAll('[data-testid]').forEach((el) => {
    if (!(el instanceof HTMLElement)) return;

    const testId = el.dataset.testid;
    if (testId?.startsWith(TEMPLATE_SLIDE_TEST_ID_PREFIX)) return;

    delete el.dataset.testid;
  });
  stripPngCopyActions(clone);

  // Inline images on the detached clone — no live DOM mutations, no repaints
  const restoreCloneImages = await inlineImagesForExport(clone, {
    imageDataFormat: 'image/jpeg',
    jpegQuality: 0.85,
  });

  const css = collectStylesheets();
  const html = `<style>${css}</style>${clone.innerHTML}`;

  restoreCloneImages();
  return html;
};

export const usePageCacheHtml = ({
  pageName,
  containerRef,
  enabled = true,
  isPageReady = false,
}: UsePageCacheHtmlProps): UsePageCacheHtmlResult => {
  const {
    cachedHtml,
    isCacheChecking,
    isCacheHit,
    isStaleHit,
    shouldRevalidate,
    setCachedHtml,
    setIsCacheChecking,
    setIsCacheHit,
    setIsStaleHit,
    setShouldRevalidate,
    checkedHashRef,
    abortControllerRef,
  } = usePageCacheBaseState();

  const { pageHash } = useResolvedPageHash(pageName);

  useEffect(() => {
    if (!enabled || !pageHash || pageHash === checkedHashRef.current) return;

    checkedHashRef.current = pageHash;

    abortControllerRef.current?.abort();
    const abortController = new AbortController();
    abortControllerRef.current = abortController;

    setIsCacheChecking(true);
    setCachedHtml(null);
    setIsCacheHit(false);
    setIsStaleHit(false);
    setShouldRevalidate(false);

    PageCacheService.getInstance()
      .get(pageName, pageHash, abortController.signal)
      .then(async (result) => {
        if (abortController.signal.aborted) return;

        if (result?.html) {
          const html = stripPngCopyActionsFromHtml(
            decompressFromBase64(result.html),
          );
          setCachedHtml(html);
          setIsCacheHit(true);
          setIsStaleHit(!!result.isStale);
          setShouldRevalidate(!!result.shouldRevalidate);
        }

        setIsCacheChecking(false);
      })
      .catch(() => {
        if (!abortController.signal.aborted) {
          setIsCacheChecking(false);
        }
      });

    return () => {
      abortController.abort();
    };
  }, [
    enabled,
    pageName,
    pageHash,
    abortControllerRef,
    checkedHashRef,
    setCachedHtml,
    setIsCacheChecking,
    setIsCacheHit,
    setIsStaleHit,
    setShouldRevalidate,
  ]);

  useEffect(() => {
    if (!enabled || !isCacheHit || !cachedHtml || !containerRef.current) return;

    return hydratePngCopyActions(containerRef.current);
  }, [enabled, isCacheHit, cachedHtml, containerRef]);

  const submittedHashRef = useRef<string>('');
  const wasLoadingRef = usePageCacheLoadingGate(
    isPageReady,
    isCacheChecking,
    isCacheHit,
    isStaleHit,
    shouldRevalidate,
  );

  useEffect(() => {
    if (!enabled || !isPageReady || !pageHash || isCacheChecking) return;

    const shouldSubmitByState = !isCacheHit || (isStaleHit && shouldRevalidate);
    if (!shouldSubmitByState) return;
    if (!wasLoadingRef.current) return;
    if (submittedHashRef.current === pageHash) return;
    if (!containerRef.current) return;

    submittedHashRef.current = pageHash;

    let cancelled = false;

    const captureAndSubmit = async () => {
      if (!containerRef.current) return;

      try {
        await waitForCanvasStability(containerRef.current);
        if (cancelled || !containerRef.current) return;

        const htmlContent = await serializeDom(containerRef.current);
        const compressed = compressToBase64(htmlContent);

        await PageCacheService.getInstance().set(
          pageName,
          pageHash,
          compressed,
        );
      } catch (error) {
        console.error('Failed to submit page to cache (innerHTML):', error);
      }
    };

    captureAndSubmit();

    return () => {
      cancelled = true;
    };
  }, [
    enabled,
    isPageReady,
    pageName,
    pageHash,
    isCacheHit,
    isStaleHit,
    shouldRevalidate,
    isCacheChecking,
    containerRef,
    wasLoadingRef,
  ]);

  return {
    cachedHtml,
    isCacheChecking,
    isCacheHit,
    isStaleHit,
    shouldRevalidate,
  };
};
